  ["catalog/init"] = function(script, require, QuartzUI_Context)
    -- Compiled with roblox-ts v3.0.0
    local TS = __QUARTZUI_TS__
    local exports = {}
    --[[
    	*
    	 * QuartzUI - catalog barrel
    	 *
    	 * Re-exports every pure-data catalog slice (icons, fonts, sounds, and
    	 * animation presets). This module is import-only - it never depends on
    	 * `core/`, `animation/`, `theme/`, or any other runtime slice.
    	 *
    	 * @module catalog
    	 * @see AGENTS.md
    	 
    ]]
    for _k, _v in TS.import(script, script, "icons") or {} do
    	exports[_k] = _v
    end
    for _k, _v in TS.import(script, script, "fonts") or {} do
    	exports[_k] = _v
    end
    for _k, _v in TS.import(script, script, "sounds") or {} do
    	exports[_k] = _v
    end
    for _k, _v in TS.import(script, script, "animations") or {} do
    	exports[_k] = _v
    end
    return exports

  end,
