    -- ---------------------------------------------------------------------------
    -- Character classifiers
    -- ---------------------------------------------------------------------------
    --* Does `ch` open an identifier? 
    local function isIdentStart(ch)
    	return (ch >= "a" and ch <= "z") or (ch >= "A" and ch <= "Z") or ch == "_" or ch == "$"
    end
    --* Does `ch` continue an identifier? 
    local function isIdentCont(ch)
    	return isIdentStart(ch) or (ch >= "0" and ch <= "9")
    end
    --* Is `ch` a digit? 
    local function isDigit(ch)
    	return ch >= "0" and ch <= "9"
    end
    --* Is `ch` one of the single-char operators? 
    local function isOperator(ch)
    	return ch == "+" or ch == "-" or ch == "*" or ch == "/" or ch == "%" or ch == "=" or ch == "<" or ch == ">" or ch == "!" or ch == "&" or ch == "|" or ch == "^" or ch == "~" or ch == "?" or ch == ":"
    end
    --* Is `ch` a standalone punctuation character? 
    local function isPunct(ch)
    	return ch == "(" or ch == ")" or ch == "[" or ch == "]" or ch == "{" or ch == "}" or ch == "," or ch == ";" or ch == "." or ch == "@"
    end
    -- ---------------------------------------------------------------------------
    -- Keyword resolution per language
    -- ---------------------------------------------------------------------------
    local function keywordsFor(lang)
    	repeat
    		local _fallthrough = false
    		if lang == "lua" then
    			return LUA_KEYWORDS
    		end
    		if lang == "luau" then
    			local out = {}
    			for k in LUA_KEYWORDS do
    				out[k] = true
    			end
    			for k in LUAU_EXTRA do
    				out[k] = true
    			end
    			return out
    		end
    		if lang == "typescript" then
    			return TS_KEYWORDS
    		end
    		if lang == "javascript" then
    			return JS_KEYWORDS
    		end
    		if lang == "plain" then
    		end
    		return {}
    	until true
    end
    local function constantsFor(lang)
    	repeat
    		local _fallthrough = false
    		if lang == "lua" then
    			_fallthrough = true
    		end
    		if _fallthrough or lang == "luau" then
    			return LUA_CONSTANTS
    		end
    		if lang == "typescript" then
    			_fallthrough = true
    		end
    		if _fallthrough or lang == "javascript" then
    			return TS_CONSTANTS
    		end
    		if lang == "plain" then
    		end
    		return {}
    	until true
    end
    -- ---------------------------------------------------------------------------
    -- Tokenizer
    -- ---------------------------------------------------------------------------
    --* Tokenize a single line with the given language flavor. 
    local function tokenizeLine(line, lang, keywords, constants)
    	local tokens = {}
    	local n = #line
    	local i = 0
    	while i < n do
    		local ch = string.sub(line, i + 1, i + 1)
    		-- Line comments: -- for Lua/Luau, // for JS/TS.
    		if (lang == "lua" or lang == "luau") and ch == "-" and string.sub(line, i + 2, i + 2) == "-" then
    			local _arg0 = {
    				kind = "comment",
    				text = string.sub(line, i + 1, n),
    			}
    			table.insert(tokens, _arg0)
    			return tokens
    		end
    		if (lang == "javascript" or lang == "typescript") and ch == "/" and string.sub(line, i + 2, i + 2) == "/" then
    			local _arg0 = {
    				kind = "comment",
    				text = string.sub(line, i + 1, n),
    			}
    			table.insert(tokens, _arg0)
    			return tokens
    		end
    		-- Strings: ', ", `.
    		if ch == "'" or ch == '"' or ch == "`" then
    			local quote = ch
    			local endIdx = i + 1
    			while endIdx < n do
    				local c = string.sub(line, endIdx + 1, endIdx + 1)
    				if c == "\\" then
    					endIdx += 2
    					continue
    				end
    				if c == quote then
    					endIdx += 1
    					break
    				end
    				endIdx += 1
    			end
    			local _arg0 = {
    				kind = "string",
    				text = string.sub(line, i + 1, endIdx),
    			}
    			table.insert(tokens, _arg0)
    			i = endIdx
    			continue
    		end
    		-- Numbers.
    		if isDigit(ch) then
    			local endIdx = i + 1
    			while endIdx < n do
    				local c = string.sub(line, endIdx + 1, endIdx + 1)
    				if isDigit(c) or c == "." or c == "x" or c == "X" or c == "e" or c == "E" then
    					endIdx += 1
    				else
    					break
    				end
    			end
    			local _arg0 = {
    				kind = "number",
    				text = string.sub(line, i + 1, endIdx),
    			}
    			table.insert(tokens, _arg0)
    			i = endIdx
    			continue
    		end
    		-- Identifiers / keywords / functions.
    		if isIdentStart(ch) then
    			local endIdx = i + 1
    			while endIdx < n do
    				local c = string.sub(line, endIdx + 1, endIdx + 1)
    				if isIdentCont(c) then
    					endIdx += 1
    				else
    					break
    				end
    			end
    			local word = string.sub(line, i + 1, endIdx)
    			local kind
    			if keywords[word] ~= nil then
    				kind = "keyword"
    			elseif constants[word] ~= nil then
    				kind = "constant"
    			else
    				local lookAhead = string.sub(line, endIdx + 1, endIdx + 1)
    				if lookAhead == "(" then
    					kind = "function"
    				else
    					kind = "identifier"
    				end
    			end
    			local _arg0 = {
    				kind = kind,
    				text = word,
    			}
    			table.insert(tokens, _arg0)
    			i = endIdx
    			continue
    		end
    		-- Whitespace chunk.
    		if ch == " " or ch == "\t" then
    			local endIdx = i + 1
    			while endIdx < n do
    				local c = string.sub(line, endIdx + 1, endIdx + 1)
    				if c == " " or c == "\t" then
    					endIdx += 1
    				else
    					break
    				end
    			end
    			local _arg0 = {
    				kind = "whitespace",
    				text = string.sub(line, i + 1, endIdx),
    			}
    			table.insert(tokens, _arg0)
    			i = endIdx
    			continue
    		end
    		-- Operators (1-3 chars).
    		if isOperator(ch) then
    			local endIdx = i + 1
    			while endIdx < n and endIdx - i < 3 do
    				local c = string.sub(line, endIdx + 1, endIdx + 1)
    				if isOperator(c) then
    					endIdx += 1
    				else
    					break
    				end
    			end
    			local _arg0 = {
    				kind = "operator",
    				text = string.sub(line, i + 1, endIdx),
    			}
    			table.insert(tokens, _arg0)
    			i = endIdx
    			continue
    		end
    		-- Punctuation.
    		if isPunct(ch) then
    			local _arg0 = {
    				kind = "punctuation",
    				text = ch,
    			}
    			table.insert(tokens, _arg0)
    			i += 1
    			continue
    		end
    		-- Anything else.
    		local _arg0 = {
    			kind = "unknown",
    			text = ch,
    		}
    		table.insert(tokens, _arg0)
    		i += 1
    	end
    	return tokens
    end
    --* Tokenize a full source string into per-line token lists. 
    local function tokenize(source, lang)
    	local keywords = keywordsFor(lang)
    	local constants = constantsFor(lang)
    	local lines = string.split(source, "\n")
    	local out = {}
    	for _, line in lines do
    		local _arg0 = tokenizeLine(line, lang, keywords, constants)
    		table.insert(out, _arg0)
    	end
    	return out
    end
    -- ---------------------------------------------------------------------------
    -- Rich text encoding
    -- ---------------------------------------------------------------------------
    --* Encode bytes hazardous to rich-text into numeric entities. 
    local function escapeRich(text)
    	local out = ""
    	local n = #text
    	do
    		local i = 0
    		local _shouldIncrement = false
    		while true do
    			if _shouldIncrement then
    				i += 1
    			else
    				_shouldIncrement = true
    			end
    			if not (i < n) then
    				break
    			end
    			local c = string.sub(text, i + 1, i + 1)
    			if c == "<" then
    				out ..= "&lt;"
    			elseif c == ">" then
    				out ..= "&gt;"
    			elseif c == "&" then
    				out ..= "&amp;"
    			elseif c == '"' then
    				out ..= "&quot;"
    			else
    				out ..= c
    			end
    		end
    	end
    	return out
    end
    --* Format a color as `#RRGGBB` for rich-text tags. 
    local function colorHex(c)
    	local r = math.floor(c.R * 255 + 0.5)
    	local g = math.floor(c.G * 255 + 0.5)
    	local b = math.floor(c.B * 255 + 0.5)
    	return string.format("#%02X%02X%02X", r, g, b)
    end
    --* Build a rich-text line from its token list. 
    local function lineToRich(tokens, style)
    	local out = ""
    	for _, t in tokens do
    		local color = style.colorFor(t.kind)
    		local text = escapeRich(t.text)
    		out ..= '<font color="' .. colorHex(color) .. '">' .. text .. "</font>"
    	end
    	return out
    end
    -- ---------------------------------------------------------------------------
    -- Gutter renderer
    -- ---------------------------------------------------------------------------
    --* Left-side line number gutter. 
    local function Gutter(props)
    	local s = props.style
    	local children = { Roact.createElement("UIListLayout", {
    		FillDirection = Enum.FillDirection.Vertical,
    		SortOrder = Enum.SortOrder.LayoutOrder,
    		Padding = UDim.new(0, 0),
    	}) }
    	do
    		local i = 1
    		local _shouldIncrement = false
    		while true do
    			if _shouldIncrement then
    				i += 1
    			else
    				_shouldIncrement = true
    			end
    			if not (i <= props.lineCount) then
    				break
    			end
    			local _arg0 = Roact.createElement("TextLabel", {
    				BackgroundTransparency = 1,
    				Font = s.font,
    				Text = tostring(i),
    				TextColor3 = s.gutterFg,
    				TextSize = s.fontSize,
    				Size = UDim2.new(1, 0, 0, s.lineHeight),
    				TextXAlignment = Enum.TextXAlignment.Right,
    				LayoutOrder = i,
    				Name = "LN_" .. tostring(i),
    			})
    			table.insert(children, _arg0)
    		end
    	end
    	local _exp = {
    		BackgroundColor3 = s.gutterBg,
    		BorderSizePixel = 0,
    		Size = UDim2.new(0, s.gutterWidth, 1, 0),
    		Name = "Gutter",
    	}
    	local _array = { Roact.createElement("UIPadding", {
    		PaddingLeft = UDim.new(0, 4),
    		PaddingRight = UDim.new(0, 4),
    		PaddingTop = UDim.new(0, s.padY),
    	}) }
    	local _length = #_array
    	table.move(children, 1, #children, _length + 1, _array)
    	return Roact.createElement("Frame", _exp, _array)
    end
    -- ---------------------------------------------------------------------------
    -- Main component
    -- ---------------------------------------------------------------------------
    --* Count newlines in `value`. 
    local function countLines(value)
    	if value == "" then
    		return 1
    	end
    	local n = 1
    	local len = #value
    	do
    		local i = 0
    		local _shouldIncrement = false
    		while true do
    			if _shouldIncrement then
    				i += 1
    			else
    				_shouldIncrement = true
    			end
    			if not (i < len) then
    				break
    			end
    			if string.sub(value, i + 1, i + 1) == "\n" then
    				n += 1
    			end
    		end
    	end
    	return n
    end
    --[[
    	*
    	 * `<CodeEditor>` — syntax-highlighted multi-line code editor.
    	 *
    	 * @example
    	 * ```tsx
    	 * <CodeEditor
    	 *   value={src}
    	 *   onChange={setSrc}
    	 *   language="luau"
    	 *   lineNumbers
    	 * />
    	 * ```
    	 
    ]]
    local function CodeEditor(props)
    	local theme = useTheme()
    	local style = Roact.useMemo(function()
    		return styleFor(theme, props)
    	end, { theme, props })
    	local lang = props.language or "plain"
    	local lineTokens = Roact.useMemo(function()
    		return tokenize(props.value, lang)
    	end, { props.value, lang })
    	local richLines = Roact.useMemo(function()
    		local out = {}
    		for _, tokens in lineTokens do
    			local _arg0 = lineToRich(tokens, style)
    			table.insert(out, _arg0)
    		end
    		return out
    	end, { lineTokens, style })
    	local richText = table.concat(richLines, "\n")
    	local lineCount = #lineTokens
    	local inputRef = Roact.useRef(nil)
    	local onTextChanged = Roact.useCallback(function(inst)
    		local text = inst.Text
    		local _condition = props.maxLength
    		if _condition == nil then
    			_condition = 0
    		end
    		local max = _condition
    		if max > 0 and #text > max then
    			text = string.sub(text, 1, max)
    			inst.Text = text
    		end
    		local _result = props.onChange
    		if _result ~= nil then
    			_result(text)
    		end
    	end, { props.onChange, props.maxLength })
    	local onMount = Roact.useCallback(function(inst)
    		inputRef.current = inst
    	end, {})
    	-- Imperative ref.
    	Roact.useEffect(function()
    		local sink = props.refSink
    		if sink == nil then
    			return nil
    		end
    		local impl = {
    			getValue = function()
    				local _result = inputRef.current
    				if _result ~= nil then
    					_result = _result.Text
    				end
    				local _condition = _result
    				if _condition == nil then
    					_condition = ""
    				end
    				return _condition
    			end,
    			setValue = function(v)
    				local inst = inputRef.current
    				if inst ~= nil then
    					inst.Text = v
    				end
    				local _result = props.onChange
    				if _result ~= nil then
    					_result(v)
    				end
    			end,
    			focus = function()
    				local _result = inputRef.current
    				if _result ~= nil then
    					_result = _result:CaptureFocus()
    				end
    				return _result
    			end,
    			blur = function()
    				local _result = inputRef.current
    				if _result ~= nil then
    					_result = _result:ReleaseFocus()
    				end
    				return _result
    			end,
    			getLineCount = function()
    				return lineCount
    			end,
    		}
    		sink(impl)
    		return function()
    			return sink(nil)
    		end
    	end, { lineCount })
    	local showGutter = props.lineNumbers ~= false
    	local gutterWidth = if showGutter then style.gutterWidth else 0
    	local contentHeight = math.max(lineCount * style.lineHeight + style.padY * 2, style.lineHeight + style.padY * 2)
    	-- Editable layer: invisible text, visible caret + selection.
    	local _object = {
    		BackgroundTransparency = 1,
    		ClearTextOnFocus = false,
    		Font = style.font,
    		MultiLine = true,
    	}
    	local _left = "PlaceholderText"
    	local _condition = props.placeholder
    	if _condition == nil then
    		_condition = ""
    	end
    	_object[_left] = _condition
    	_object.PlaceholderColor3 = style.placeholderFg
    	_object.Text = props.value
    	_object.TextColor3 = style.bg
    	_object.TextTransparency = 1
    	_object.TextSize = style.fontSize
    	_object.TextXAlignment = Enum.TextXAlignment.Left
    	_object.TextYAlignment = Enum.TextYAlignment.Top
    	_object.TextWrapped = props.wrap == true
    	_object.Size = UDim2.new(1, -gutterWidth, 0, contentHeight)
    	_object.Position = UDim2.new(0, gutterWidth, 0, 0)
    	_object.TextEditable = props.readonly ~= true
    	_object.Name = "Editor"
    	_object[Roact.Change.Text] = onTextChanged
    	_object[Roact.Ref] = onMount
    	local editor = Roact.createElement("TextBox", _object)
    	-- Display layer: rich-text colorized version.
    	local display = Roact.createElement("TextLabel", {
    		BackgroundTransparency = 1,
    		Font = style.font,
    		RichText = true,
    		Text = richText,
    		TextColor3 = style.placeholderFg,
    		TextSize = style.fontSize,
    		TextXAlignment = Enum.TextXAlignment.Left,
    		TextYAlignment = Enum.TextYAlignment.Top,
    		TextWrapped = props.wrap == true,
    		Size = UDim2.new(1, -gutterWidth, 0, contentHeight),
    		Position = UDim2.new(0, gutterWidth, 0, 0),
    		Name = "Display",
    	})
    	local scrollChildren = { display, editor }
    	local outerChildren = { Roact.createElement("UICorner", {
    		CornerRadius = style.radius,
    	}), Roact.createElement("UIStroke", {
    		Color = style.stroke,
    		Thickness = 1,
    	}), Roact.createElement("UIPadding", {
    		PaddingTop = UDim.new(0, style.padY),
    		PaddingBottom = UDim.new(0, style.padY),
    		PaddingLeft = UDim.new(0, style.padX),
    		PaddingRight = UDim.new(0, style.padX),
    	}) }
    	if showGutter then
    		local _arg0 = Roact.createElement(Gutter, {
    			style = style,
    			lineCount = lineCount,
    		})
    		table.insert(outerChildren, _arg0)
    	end
    	local _arg0 = Roact.createElement(ScrollArea, {
    		direction = "y",
    		canvasSize = UDim2.new(1, 0, 0, contentHeight),
    		size = UDim2.new(1, 0, 1, 0),
    	}, { Roact.createElement("Frame", {
    		BackgroundTransparency = 1,
    		Size = UDim2.new(1, 0, 0, contentHeight),
    		Name = "Code",
    	}, scrollChildren) })
    	table.insert(outerChildren, _arg0)
    	local _object_1 = {
    		BackgroundColor3 = style.bg,
    		BorderSizePixel = 0,
    		ClipsDescendants = true,
    		Size = props.size or UDim2.new(1, 0, 1, 0),
    		Position = props.position,
    		AnchorPoint = props.anchorPoint,
    		LayoutOrder = props.layoutOrder,
    		Visible = props.visible ~= false,
    	}
    	local _left_1 = "ZIndex"
    	local _condition_1 = props.zIndex
    	if _condition_1 == nil then
    		_condition_1 = 1
    	end
    	_object_1[_left_1] = _condition_1
    	local _left_2 = "Name"
    	local _condition_2 = props.id
    	if _condition_2 == nil then
    		_condition_2 = "CodeEditor"
    	end
    	_object_1[_left_2] = _condition_2
