    	[ZLayer.Elevated] = 0,
    	[ZLayer.Overlay] = 0,
    	[ZLayer.Modal] = 0,
    	[ZLayer.Toast] = 0,
    	[ZLayer.Tooltip] = 0,
    	[ZLayer.Debug] = 0,
    }
    local perLayerLive = {
    	[ZLayer.Base] = {},
    	[ZLayer.Elevated] = {},
    	[ZLayer.Overlay] = {},
    	[ZLayer.Modal] = {},
    	[ZLayer.Toast] = {},
    	[ZLayer.Tooltip] = {},
    	[ZLayer.Debug] = {},
