    --[[
    	*
    	 * Create a Button. Returns a chainable handle.
    	 
    ]]
    local function buildButton(props, context)
    	local merged = mergeWithDefaults({
    		variant = "primary",
    	}, props)
    	local handle = createHandle({
    		widget = "Button",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		OnClick = function(self, fn)
    			attachListener(handle, "onClick", fn)
    			return handle
    		end,
    		Label = function(self, text)
    			handle:Set({
    				text = text,
    			})
    			return handle
    		end,
    		Variant = function(self, v)
    			handle:Set({
    				variant = v,
    			})
    			return handle
    		end,
    		LeadingIcon = function(self, asset)
    			handle:Set({
    				leadingIcon = asset,
    			})
    			return handle
    		end,
    		TrailingIcon = function(self, asset)
    			handle:Set({
    				trailingIcon = asset,
    			})
    			return handle
    		end,
    		Click = function(self)
    			local onClick = handle:Get().onClick
    			if onClick ~= nil then
    				local ok, err = pcall(function()
    					return onClick()
    				end)
    				if not ok then
    					warn(`[QuartzUI] Button.Click(): {err}`)
    				end
    			end
    			return handle
    		end,
    	})
    end
