    --[[
    	*
    	 * Create a Toggle.
    	 
    ]]
    local function buildToggle(props, context)
    	local merged = mergeWithDefaults({
    		value = false,
    	}, props)
    	local handle = createHandle({
    		widget = "Toggle",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetValue = function(self, value)
    			handle:Set({
    				value = value,
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb(value)
    			end
    			return handle
    		end,
    		GetValue = function(self)
    			return handle:Get().value == true
    		end,
    		Flip = function(self)
    			local nextVal = handle:Get().value ~= true
    			handle:Set({
    				value = nextVal,
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb(nextVal)
    			end
    			return handle
    		end,
    		OnChange = function(self, fn)
    			attachValueListener(handle, "onChange", fn)
    			return handle
    		end,
    	})
    end
    --[[
    	*
    	 * Create a Slider.
    	 
    ]]
    local function buildSlider(props, context)
    	local merged = mergeWithDefaults({
    		value = 0,
    		min = 0,
    		max = 100,
    		step = 1,
    	}, props)
    	local handle = createHandle({
    		widget = "Slider",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetValue = function(self, value)
    			handle:Set({
    				value = value,
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb(value)
    			end
    			return handle
    		end,
    		GetValue = function(self)
    			local _condition = handle:Get().value
    			if _condition == nil then
    				_condition = 0
    			end
    			return _condition
    		end,
    		Range = function(self, min, max)
    			handle:Set({
    				min = min,
    				max = max,
    			})
    			return handle
    		end,
    		Step = function(self, step)
    			handle:Set({
    				step = step,
    			})
    			return handle
    		end,
    		OnChange = function(self, fn)
    			attachValueListener(handle, "onChange", fn)
    			return handle
    		end,
    	})
    end
    --[[
