    	}, props)
    	local handle = createHandle({
    		widget = "RangeSlider",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetRange = function(self, low, high)
    			handle:Set({
    				value = { low, high },
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb({ low, high })
    			end
    			return handle
    		end,
    		GetRange = function(self)
    			local v = handle:Get().value
    			return v or { 0, 0 }
    		end,
    		Bounds = function(self, min, max)
    			handle:Set({
    				min = min,
    				max = max,
    			})
    			return handle
    		end,
    		OnChange = function(self, fn)
    			attachValueListener(handle, "onChange", fn)
    			return handle
    		end,
    	})
    end
