    --[[
    	*
    	 * Create a MultiSelect.
    	 
    ]]
    local function buildMultiSelect(props, context)
    	local merged = mergeWithDefaults({
    		options = {},
    		value = {},
    	}, props)
    	local handle = createHandle({
    		widget = "MultiSelect",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetValue = function(self, value)
    			handle:Set({
    				value = value,
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb(value)
    			end
    			return handle
    		end,
    		GetValue = function(self)
    			return handle:Get().value or {}
    		end,
    		Toggle = function(self, value)
    			local current = handle:Get().value or {}
    			local out = {}
    			local removed = false
    			for _, entry in current do
    				if entry == value then
    					removed = true
    				else
    					table.insert(out, entry)
    				end
    			end
    			if not removed then
    				local _value = value
    				table.insert(out, _value)
    			end
    			handle:Set({
    				value = out,
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb(out)
    			end
    			return handle
    		end,
    		OnChange = function(self, fn)
    			attachValueListener(handle, "onChange", fn)
    			return handle
    		end,
    	})
    end
