    --[[
    	*
    	 * Create a Toast.
    	 
    ]]
    local function buildToast(props, context)
    	local merged = mergeWithDefaults({
    		variant = "info",
    		duration = 4,
    	}, props)
    	local handle = createHandle({
    		widget = "Toast",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetText = function(self, text)
    			handle:Set({
    				text = text,
    			})
    			return handle
    		end,
    		Title = function(self, title)
    			handle:Set({
    				title = title,
    			})
    			return handle
    		end,
    		Variant = function(self, v)
    			handle:Set({
    				variant = v,
    			})
    			return handle
    		end,
    		Duration = function(self, seconds)
    			handle:Set({
    				duration = seconds,
    			})
    			return handle
    		end,
    		Close = function(self)
    			local cb = handle:Get().onClose
    			if cb ~= nil then
    				local ok = pcall(cb)
    				if not ok then
    					warn("[QuartzUI] Toast.onClose failed")
    				end
    			end
    			handle.Destroy()
    		end,
    		OnClose = function(self, fn)
    			attachListener(handle, "onClose", fn)
    			return handle
    		end,
    	})
    end
