    	})
    	return attachAll(handle, {
    		SetText = function(self, text)
    			handle:Set({
    				text = text,
    			})
    			return handle
    		end,
    		Title = function(self, title)
    			handle:Set({
    				title = title,
    			})
    			return handle
    		end,
    		Variant = function(self, v)
    			handle:Set({
    				variant = v,
    			})
    			return handle
    		end,
    		Duration = function(self, seconds)
    			handle:Set({
    				duration = seconds,
    			})
    			return handle
    		end,
    		Close = function(self)
    			local cb = handle:Get().onClose
    			if cb ~= nil then
    				local ok = pcall(cb)
    				if not ok then
    					warn("[QuartzUI] Notification.onClose failed")
    				end
    			end
    			handle.Destroy()
    		end,
    		OnClose = function(self, fn)
    			attachListener(handle, "onClose", fn)
    			return handle
    		end,
    		AddAction = function(self, label, fn)
    			local existing = handle:Get().actions or {}
    			local out = {}
    			for _, item in existing do
    				table.insert(out, item)
    			end
    			local _arg0 = {
    				label = label,
    				onClick = fn,
    			}
    			table.insert(out, _arg0)
    			handle:Set({
    				actions = out,
    			})
    			return handle
    		end,
    	})
    end
    --[[
    	*
    	 * Create a Dialog. Prefer `QuartzUI.Dialog(..)` which wraps this in a
    	 * Promise; the builder is used directly only when callers need the
    	 * raw handle.
    	 
    ]]
    local function buildDialog(props, context)
    	local merged = mergeWithDefaults({
    		confirmLabel = "OK",
    		cancelLabel = "Cancel",
    		variant = "info",
    		confirmOnly = false,
    	}, props)
    	local handle = createHandle({
    		widget = "Dialog",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetBody = function(self, text)
    			handle:Set({
    				body = text,
    			})
    			return handle
    		end,
    		SetTitle = function(self, text)
    			handle:Set({
    				title = text,
    			})
    			return handle
    		end,
    		OnConfirm = function(self, fn)
    			attachListener(handle, "onConfirm", fn)
    			return handle
    		end,
    		OnCancel = function(self, fn)
    			attachListener(handle, "onCancel", fn)
    			return handle
    		end,
    		Confirm = function(self)
    			local cb = handle:Get().onConfirm
    			if cb ~= nil then
    				local ok = pcall(cb)
    				if not ok then
    					warn("[QuartzUI] Dialog.onConfirm failed")
    				end
    			end
    			handle.Destroy()
    		end,
    		Cancel = function(self)
    			local cb = handle:Get().onCancel
    			if cb ~= nil then
    				local ok = pcall(cb)
    				if not ok then
    					warn("[QuartzUI] Dialog.onCancel failed")
    				end
    			end
    			handle.Destroy()
    		end,
    	})
    end
