    --[[
    	*
    	 * Create a CodeEditor.
    	 
    ]]
    local function buildCodeEditor(props, context)
    	local merged = mergeWithDefaults({
    		value = "",
    		language = "luau",
    		readOnly = false,
    	}, props)
    	local handle = createHandle({
    		widget = "CodeEditor",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetValue = function(self, value)
    			handle:Set({
    				value = value,
    			})
    			local cb = handle:Get().onChange
    			if cb ~= nil then
    				cb(value)
    			end
    			return handle
    		end,
    		GetValue = function(self)
    			local _condition = handle:Get().value
    			if _condition == nil then
    				_condition = ""
    			end
    			return _condition
    		end,
    		Language = function(self, lang)
    			handle:Set({
    				language = lang,
    			})
    			return handle
    		end,
    		ReadOnly = function(self, on)
    			handle:Set({
    				readOnly = on,
    			})
    			return handle
    		end,
    		OnChange = function(self, fn)
    			attachValueListener(handle, "onChange", fn)
    			return handle
    		end,
    	})
    end
    --[[
    	*
    	 * Create a Terminal.
    	 
    ]]
    local function buildTerminal(props, context)
    	local merged = mergeWithDefaults({
    		lines = {},
    		prompt = "> ",
    	}, props)
    	local handle = createHandle({
    		widget = "Terminal",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		Append = function(self, line)
    			local prev = handle:Get().lines or {}
    			local out = {}
    			for _, entry in prev do
    				table.insert(out, entry)
    			end
    			local _line = line
    			table.insert(out, _line)
    			handle:Set({
    				lines = out,
    			})
    			return handle
    		end,
    		Clear = function(self)
    			handle:Set({
    				lines = {},
    			})
    			return handle
    		end,
    		Prompt = function(self, prompt)
    			handle:Set({
    				prompt = prompt,
    			})
    			return handle
    		end,
    		OnSubmit = function(self, fn)
    			attachValueListener(handle, "onSubmit", fn)
    			return handle
    		end,
    	})
    end
    --[[
    	*
    	 * Create a Drawer.
    	 
    ]]
    local function buildDrawer(props, context)
    	local merged = mergeWithDefaults({
    		open = false,
    		side = "right",
    	}, props)
    	local handle = createHandle({
    		widget = "Drawer",
    		props = normaliseProps(merged),
    		parent = context,
    	})
    	return attachAll(handle, {
    		Open = function(self)
    			handle:Set({
    				open = true,
    			})
    			local cb = handle:Get().onOpenChange
    			if cb ~= nil then
    				cb(true)
    			end
    			return handle
    		end,
    		Close = function(self)
    			handle:Set({
    				open = false,
    			})
    			local cb = handle:Get().onOpenChange
    			if cb ~= nil then
    				cb(false)
    			end
    			return handle
    		end,
    		Toggle = function(self)
    			local nextOpen = handle:Get().open ~= true
    			handle:Set({
    				open = nextOpen,
    			})
    			local cb = handle:Get().onOpenChange
    			if cb ~= nil then
    				cb(nextOpen)
    			end
    			return handle
    		end,
    		Side = function(self, side)
    			handle:Set({
    				side = side,
    			})
    			return handle
    		end,
    		OnOpenChange = function(self, fn)
    			attachValueListener(handle, "onOpenChange", fn)
    			return handle
    		end,
    	})
    end
