    --[[
    	*
    	 * Create a ScriptRunner.
    	 
    ]]
    local function buildScriptRunner(props, context)
    	local handle = createHandle({
    		widget = "ScriptRunner",
    		props = normaliseProps(props),
    		parent = context,
    	})
    	return attachAll(handle, {
    		SetSource = function(self, source)
    			handle:Set({
    				initialSource = source,
    			})
    			return handle
    		end,
    		OnRun = function(self, fn)
    			attachValueListener(handle, "onRun", fn)
    			return handle
    		end,
    		Run = function(self)
    			local _condition = handle:Get().initialSource
    			if _condition == nil then
    				_condition = ""
    			end
    			local source = _condition
    			local cb = handle:Get().onRun
    			if cb ~= nil then
    				local ok = pcall(function()
    					return cb(source)
    				end)
    				if not ok then
    					warn("[QuartzUI] ScriptRunner.Run failed")
    				end
    			end
    			return handle
    		end,
    	})
    end
    --[[
    	*
    	 * Placeholder builder that creates a handle with no chain methods.
    	 * Used internally when a caller asks for a widget that has no
    	 * hand-written builder registered yet.
    	 
    ]]
    local function buildFallback(widget, props, context)
    	return emptyHandle(widget, props, context)
    end
    --* Re-export helpers used by hand-written builders. 
    --[[
    	*
    	 * Map of simple widget builders keyed by their canonical name.
    	 * Used by the imperative runtime as a generic fallback registry
    	 * when a typed builder does not exist.
    	 
    ]]
    local SIMPLE_BUILDERS = {
    	button = buildButton,
    	iconButton = buildIconButton,
    	toggle = buildToggle,
    	slider = buildSlider,
    	rangeSlider = buildRangeSlider,
    	label = buildLabel,
    	paragraph = buildParagraph,
    	image = buildImage,
    	icon = buildIcon,
    	badge = buildBadge,
    	avatar = buildAvatar,
    	divider = buildDivider,
    	tooltip = buildTooltip,
    	progress = buildProgress,
    	spinner = buildSpinner,
    	skeleton = buildSkeleton,
    }
    return {
    	buildButton = buildButton,
    	buildIconButton = buildIconButton,
    	buildToggle = buildToggle,
    	buildSlider = buildSlider,
    	buildRangeSlider = buildRangeSlider,
    	buildDropdown = buildDropdown,
    	buildMultiSelect = buildMultiSelect,
    	buildTextInput = buildTextInput,
    	buildTextArea = buildTextArea,
    	buildComboBox = buildComboBox,
    	buildKeybind = buildKeybind,
    	buildColorPicker = buildColorPicker,
    	buildGradientEditor = buildGradientEditor,
    	buildVectorInput = buildVectorInput,
    	buildDatePicker = buildDatePicker,
    	buildLabel = buildLabel,
    	buildParagraph = buildParagraph,
    	buildImage = buildImage,
    	buildIcon = buildIcon,
    	buildBadge = buildBadge,
    	buildAvatar = buildAvatar,
    	buildDivider = buildDivider,
    	buildTooltip = buildTooltip,
    	buildProgress = buildProgress,
    	buildCircularProgress = buildCircularProgress,
    	buildSpinner = buildSpinner,
    	buildSkeleton = buildSkeleton,
