    	 * @param tokens Fully populated theme tokens.
    	 
    ]]
    local function registerPreset(name, tokens)
    	local _name = name
    	if not (presets[_name] ~= nil) then
    		local _name_1 = name
    		table.insert(insertionOrder, _name_1)
    	end
    	local _name_1 = name
    	local _tokens = tokens
    	presets[_name_1] = _tokens
    end
    --[[
    	*
    	 * Fetches a preset by name. Returns `undefined` if not registered.
    	 
