    local strict = require(script.Parent.strict)

    local Type = newproxy(true)

    local TypeInternal = {}

    local function addType(name)
    	TypeInternal[name] = Symbol.named("Roact" .. name)
    end

    addType("Binding")
    addType("Element")
    addType("HostChangeEvent")
    addType("HostEvent")
    addType("StatefulComponentClass")
    addType("StatefulComponentInstance")
    addType("VirtualNode")
    addType("VirtualTree")

    function TypeInternal.of(value)
    	if typeof(value) ~= "table" then
    		return nil
    	end

    	return value[Type]
    end

    getmetatable(Type).__index = TypeInternal

    getmetatable(Type).__tostring = function()
    	return "RoactType"
    end

    strict(TypeInternal, "Type")

    return Type

  end,
  ["@rbxts/roact/src/assertDeepEqual"] = function(script, require, QuartzUI_Context)
    --!strict
    --[[
    	A utility used to assert that two objects are value-equal recursively. It
    	outputs fairly nicely formatted messages to help diagnose why two objects
    	would be different.

    	This should only be used in tests.
    ]]

    local function deepEqual(a: any, b: any): (boolean, string?)
    	if typeof(a) ~= typeof(b) then
    		local message = ("{1} is of type %s, but {2} is of type %s"):format(typeof(a), typeof(b))
    		return false, message
    	end

    	if typeof(a) == "table" then
    		local visitedKeys = {}

    		for key, value in pairs(a) do
    			visitedKeys[key] = true

    			local success, innerMessage = deepEqual(value, b[key])
    			if not success and innerMessage then
    				local message = innerMessage
    					:gsub("{1}", ("{1}[%s]"):format(tostring(key)))
    					:gsub("{2}", ("{2}[%s]"):format(tostring(key)))

    				return false, message
    			end
    		end

    		for key, value in pairs(b) do
    			if not visitedKeys[key] then
    				local success, innerMessage = deepEqual(value, a[key])

    				if not success and innerMessage then
    					local message = innerMessage
    						:gsub("{1}", ("{1}[%s]"):format(tostring(key)))
    						:gsub("{2}", ("{2}[%s]"):format(tostring(key)))

    					return false, message
    				end
    			end
    		end

    		return true, nil
    	end

    	if a == b then
    		return true, nil
    	end

    	local message = "{1} ~= {2}"
    	return false, message
    end

    local function assertDeepEqual(a, b)
    	local success, innerMessageTemplate = deepEqual(a, b)

    	if not success and innerMessageTemplate then
    		local innerMessage = innerMessageTemplate:gsub("{1}", "first"):gsub("{2}", "second")

    		local message = ("Values were not deep-equal.\n%s"):format(innerMessage)

    		error(message, 2)
    	end
    end

    return assertDeepEqual

  end,
  ["@rbxts/roact/src/assign"] = function(script, require, QuartzUI_Context)
    local None = require(script.Parent.None)

    --[[
    	Merges values from zero or more tables onto a target table. If a value is
    	set to None, it will instead be removed from the table.

    	This function is identical in functionality to JavaScript's Object.assign.
    ]]
    local function assign(target, ...)
    	for index = 1, select("#", ...) do
    		local source = select(index, ...)

    		if source ~= nil then
    			for key, value in pairs(source) do
    				if value == None then
    					target[key] = nil
    				else
    					target[key] = value
    				end
    			end
    		end
    	end

    	return target
    end

    return assign

  end,
  ["@rbxts/roact/src/createContext"] = function(script, require, QuartzUI_Context)
    local Symbol = require(script.Parent.Symbol)
    local createFragment = require(script.Parent.createFragment)
    local createSignal = require(script.Parent.createSignal)
    local Children = require(script.Parent.PropMarkers.Children)
    local Component = require(script.Parent.Component)

    --[[
    	Construct the value that is assigned to Roact's context storage.
