    			local proxyComponent

    			if pureComponent.isPureComponent(component) or forcePureComponent then
    				proxyComponent = hoc.withHooksPure(component)
    			else
    				proxyComponent = hoc.withHooks(component)
    			end

    			if debugMode then
    				local render = proxyComponent.render

    				function proxyComponent:render(...)
    					debug.profilebegin(self._name)
    					local success, result = pcall(render, self, ...)
    					debug.profileend()

    					if not success then
    						error(result, 2)
    					end

    					return result
    				end
    			end

    			proxyComponents[component] = proxyComponent

    			return createElement(proxyComponent, props, children)
    		else
    			-- Mark this component as stateless so we don't have to check it again
    			statelessComponents[component] = true
    			return createElement(component, props, children)
    		end
    	end

    	return Roact
    end

    return withHookDetection

  end,
  ["@rbxts/services/init"] = function(script, require, QuartzUI_Context)
    return setmetatable({}, {
    	__index = function(self, serviceName)
    		local service = game:GetService(serviceName)
    		self[serviceName] = service
    		return service
    	end,
    })

  end,
  ["@rbxts/maid/Maid"] = function(script, require, QuartzUI_Context)
    ---	Manages the cleaning of events and other things.
    -- Useful for encapsulating state and make deconstructors easy
    -- @classmod Maid
    -- @see Signal

    local Maid = {}
    Maid.ClassName = "Maid"

    --- Returns a new Maid object
    -- @constructor Maid.new()
    -- @treturn Maid
    function Maid.new()
    	local self = {}

    	self._tasks = {}

    	return setmetatable(self, Maid)
    end

    --- Returns Maid[key] if not part of Maid metatable
    -- @return Maid[key] value
    function Maid:__index(index)
    	if Maid[index] then
    		return Maid[index]
    	else
    		return self._tasks[index]
    	end
    end

    --- Add a task to clean up
    -- @usage
    -- Maid[key] = (function)         Adds a task to perform
    -- Maid[key] = (event connection) Manages an event connection
    -- Maid[key] = (thread)           Manages a thread
    -- Maid[key] = (Maid)             Maids can act as an event connection, allowing a Maid to have other maids to clean up.
    -- Maid[key] = (Object)           Maids can cleanup objects with a `Destroy` method
    -- Maid[key] = nil                Removes a named task. If the task is an event, it is disconnected. If it is an object,
    --                                it is destroyed.
    function Maid:__newindex(index, newTask)
    	if Maid[index] ~= nil then
    		error(("Cannot use '%s' as a Maid key"):format(tostring(index)), 2)
    	end

    	local tasks = self._tasks
    	local oldTask = tasks[index]

    	if oldTask == newTask then
            	return
    	end

    	tasks[index] = newTask

    	if oldTask then
    		if type(oldTask) == "function" then
    			oldTask()
    		elseif type(oldTask) == "thread" then
    			local cancelled
    			if coroutine.running() ~= oldTask then
    				cancelled = pcall(function()
    					task.cancel(oldTask)
    				end)
    			end

    			if not cancelled then
    				task.defer(function()
    					task.cancel(oldTask)
    				end)
    			end
    		elseif typeof(oldTask) == "RBXScriptConnection" then
    			oldTask:Disconnect()
    		elseif oldTask.Destroy then
    			oldTask:Destroy()
    		end
    	end
    end

    --- Same as indexing, but uses an incremented number as a key.
    -- @param task An item to clean
    -- @treturn number taskId
    function Maid:GiveTask(task)
    	assert(task, "Task cannot be false or nil")

    	local taskId = #self._tasks+1
    	self[taskId] = task

    	if type(task) == "table" and (not task.Destroy) then
    		warn("[Maid.GiveTask] - Gave table task without .Destroy\n\n" .. debug.traceback())
    	end

    	return taskId
    end

    function Maid:GivePromise(promise)
    	if not promise:IsPending() then
    		return promise
    	end

    	local newPromise = promise.resolved(promise)
    	local id = self:GiveTask(newPromise)

    	-- Ensure GC
    	newPromise:Finally(function()
    		self[id] = nil
    	end)

    	return newPromise
    end

    --- Cleans up all tasks.
    -- @alias Destroy
    function Maid:DoCleaning()
    	local tasks = self._tasks

    	-- Disconnect all events first as we know this is safe
    	for index, job in pairs(tasks) do
    		if typeof(job) == "RBXScriptConnection" then
    			tasks[index] = nil
    			job:Disconnect()
    		end
    	end

    	-- Clear out tasks table completely, even if clean up tasks add more tasks to the maid
    	local index, job = next(tasks)
    	while job ~= nil do
    		tasks[index] = nil
    		if type(job) == "function" then
    			job()
    		elseif type(job) == "thread" then
    			local cancelled
    			if coroutine.running() ~= job then
    				cancelled = pcall(function()
    					task.cancel(job)
    				end)
    			end

    			if not cancelled then
    				local toCancel = job
    				task.defer(function()
    					task.cancel(toCancel)
    				end)
    			end
    		elseif typeof(job) == "RBXScriptConnection" then
    			job:Disconnect()
    		elseif job.Destroy then
    			job:Destroy()
    		end
    		index, job = next(tasks)
    	end
    end

    --- Alias for DoCleaning()
    -- @function Destroy
    Maid.Destroy = Maid.DoCleaning

    return Maid

  end,
}
table.freeze(__QUARTZUI_REGISTRY__)


local __QUARTZUI_REAL_REQUIRE__ = nil
do
  local ok, realRequire = pcall(function()
    return require
  end)
  if ok and type(realRequire) == "function" then
    __QUARTZUI_REAL_REQUIRE__ = realRequire
  end
end

local __QUARTZUI_CACHE__ = {}
local __QUARTZUI_LOADING__ = {}
local __QUARTZUI_EXTERNS__ = {}

local __QUARTZUI_CONTEXT__ = {
  namespace = "QuartzUI",
  version = "0.1.0",
  caller = nil,
}

local function __quartzui_split(path)
  local parts = {}
  local buf = ""
  for i = 1, #path do
    local c = string.sub(path, i, i)
    if c == "/" then
      if #buf > 0 then
        table.insert(parts, buf)
        buf = ""
      end
    else
      buf = buf .. c
    end
  end
  if #buf > 0 then
    table.insert(parts, buf)
  end
  return parts
end

local function __quartzui_join(parts)
  local out = ""
  for i = 1, #parts do
    if i > 1 then
      out = out .. "/"
    end
    out = out .. parts[i]
  end
  return out
end

local function __quartzui_dir_of(modulePath)
  if modulePath == nil or modulePath == "" then return "" end
  if modulePath == "init" then return "" end
  if string.sub(modulePath, -5) == "/init" then
    return string.sub(modulePath, 1, -6)
  end
  local parts = __quartzui_split(modulePath)
  if #parts <= 1 then return "" end
  table.remove(parts, #parts)
  return __quartzui_join(parts)
end

local function __quartzui_resolve(callerPath, target)
  if string.sub(target, 1, 1) == "@" then
    return target, true
  end
  if string.sub(target, 1, 2) ~= "./" and string.sub(target, 1, 3) ~= "../" then
    return target, false
  end
  local callerParts = __quartzui_split(callerPath or "")
  if #callerParts > 0 then
    table.remove(callerParts, #callerParts)
  end
  local relParts = __quartzui_split(target)
  for _, seg in ipairs(relParts) do
    if seg == "." then
      -- noop
    elseif seg == ".." then
      if #callerParts > 0 then
        table.remove(callerParts, #callerParts)
      end
    else
      table.insert(callerParts, seg)
    end
  end
  return __quartzui_join(callerParts), false
end

local function __quartzui_forward_rbxts(modulePath)
  local cached = __QUARTZUI_EXTERNS__[modulePath]
  if cached ~= nil then
    return cached, nil
  end
  if __QUARTZUI_REAL_REQUIRE__ == nil then
    return nil, "real require unavailable for " .. modulePath
  end
  local ok, result = pcall(__QUARTZUI_REAL_REQUIRE__, modulePath)
  if ok then
    __QUARTZUI_EXTERNS__[modulePath] = result
    return result, nil
  end
  return nil, tostring(result)
end

-- script proxy: behaves like a Roblox Instance for child/parent traversal.
--
-- Conventions:
--   __quartzuiPath      = logical module key (what the registry uses)
--   __quartzuiDir       = folder path used for child lookups; script.X -> <dir>/X
--   __quartzuiParentDir = folder path returned by script.Parent
--
-- For an init module at path "a/b/init", the script conceptually IS the
-- folder "a/b", so children live at "a/b/..." and Parent points to "a".
-- For a regular module at "a/b/c", the script is a plain ModuleScript
-- inside folder "a/b"; Parent points to "a/b" and child lookups are the
-- same folder (they resolve to the scripts siblings).
local __quartzui_script_mt = {}

local function __quartzui_is_init(modulePath)
  if modulePath == "init" then return true end
  if modulePath == nil or modulePath == "" then return false end
  if string.sub(modulePath, -5) == "/init" then return true end
  return false
end

local function __quartzui_make_proxy(modulePath, isFolder, parentDir)
  local dir
  local pDir
  if isFolder then
    dir = modulePath
    pDir = __quartzui_dir_of(modulePath)
  elseif __quartzui_is_init(modulePath) then
    dir = __quartzui_dir_of(modulePath)
    pDir = __quartzui_dir_of(dir)
  else
    dir = __quartzui_dir_of(modulePath)
    pDir = dir
  end
  if parentDir ~= nil then pDir = parentDir end
  local name
  if modulePath == nil or modulePath == "" then
    name = "Root"
  else
    local parts = __quartzui_split(modulePath)
    name = parts[#parts] or modulePath
  end
  return setmetatable({
    Name = name,
    ClassName = isFolder and "Folder" or "ModuleScript",
    __quartzuiPath = modulePath,
    __quartzuiDir = dir,
    __quartzuiParentDir = pDir,
    __quartzuiIsFolder = isFolder,
  }, __quartzui_script_mt)
end

__quartzui_script_mt.__index = function(self, key)
  if type(key) ~= "string" then return nil end
  -- Never synthesize values for internal fields the shim itself reads; any
  -- unresolved underscore-prefixed field must stay nil so the runtime can
  -- discriminate real proxies from external markers.
  if string.sub(key, 1, 2) == "__" then return nil end
  if key == "Parent" then
    local parentPath = rawget(self, "__quartzuiParentDir") or ""
    return __quartzui_make_proxy(parentPath, true, __quartzui_dir_of(parentPath))
  end
  if key == "WaitForChild" or key == "FindFirstChild" then
    return function(_, childName)
      local base = rawget(self, "__quartzuiDir") or ""
      local childPath
      if base == "" then childPath = tostring(childName) else childPath = base .. "/" .. tostring(childName) end
      return __quartzui_make_proxy(childPath, true, base)
    end
  end
  if key == "GetFullName" then
    return function() return rawget(self, "__quartzuiPath") or rawget(self, "Name") end
  end
  if key == "Name" or key == "ClassName" then return nil end
  -- Any other string key is treated as a child lookup, mirroring Instance.__index.
  local base = rawget(self, "__quartzuiDir") or ""
  local childPath
  if base == "" then childPath = key else childPath = base .. "/" .. key end
  return __quartzui_make_proxy(childPath, true, base)
end

local function __quartzui_registry_has(path)
  return __QUARTZUI_REGISTRY__[path] ~= nil
end

local function __quartzui_canonical(path)
  -- Try the exact path first, then fall back to <path>/init to handle the
  -- Roblox init.lua-is-the-folder convention.
  if __quartzui_registry_has(path) then return path end
  local initPath
  if path == "" then initPath = "init" else initPath = path .. "/init" end
  if __quartzui_registry_has(initPath) then return initPath end
  return path
end

local function __quartzui_target_to_path(target)
  if type(target) == "string" then return target, nil end
  if type(target) == "table" then
    if target.__quartzuiExternal ~= nil then
      return target.__quartzuiExternal, "external"
    end
    if target.__quartzuiPath ~= nil then
      return target.__quartzuiPath, nil
    end
  end
  return nil, "unsupported"
end

local __quartzui_require
__quartzui_require = function(target)
  local rawPath, kind = __quartzui_target_to_path(target)
  if rawPath == nil then
    error("[QuartzUI] require: unsupported target of type " .. type(target), 2)
  end
  local callerPath = __QUARTZUI_CONTEXT__.caller
  local resolved, isExternal
  if kind == "external" or string.sub(rawPath, 1, 1) == "@" then
    resolved = rawPath
    isExternal = true
  else
    resolved, isExternal = __quartzui_resolve(callerPath, rawPath)
  end
  resolved = __quartzui_canonical(resolved)

  local cached = __QUARTZUI_CACHE__[resolved]
  if cached ~= nil then
    return cached.value
  end

  local factory = __QUARTZUI_REGISTRY__[resolved]
  if factory == nil then
    if isExternal then
      local result, err = __quartzui_forward_rbxts(resolved)
      if err ~= nil then
        error("[QuartzUI] external require failed: " .. err, 2)
      end
      __QUARTZUI_CACHE__[resolved] = { value = result }
      return result
    end
    error("[QuartzUI] module not found: " .. tostring(resolved), 2)
  end

  if __QUARTZUI_LOADING__[resolved] then
    error(
      "[QuartzUI] circular require detected for module " .. resolved,
      2
    )
  end
  __QUARTZUI_LOADING__[resolved] = true
  local prevCaller = __QUARTZUI_CONTEXT__.caller
  __QUARTZUI_CONTEXT__.caller = resolved
  local scriptProxy = __quartzui_make_proxy(resolved, false)
  local ok, result = pcall(factory, scriptProxy, __quartzui_require, __QUARTZUI_CONTEXT__)
  __QUARTZUI_CONTEXT__.caller = prevCaller
  __QUARTZUI_LOADING__[resolved] = nil
  if not ok then
    error(
      "[QuartzUI] error while loading module " .. resolved .. ": " .. tostring(result),
      2
    )
  end
  if result == nil then
    result = true
  end
  __QUARTZUI_CACHE__[resolved] = { value = result }
  return result
end

-- ---------------------------------------------------------------------------
-- roblox-ts TS runtime shim
-- Emits the same surface as node_modules/roblox-ts/include/RuntimeLib.lua
-- but routes imports through the QuartzUI registry + forwarding shim.
-- ---------------------------------------------------------------------------
__QUARTZUI_TS__ = {}

__QUARTZUI_TS__.TRY_RETURN = 1
__QUARTZUI_TS__.TRY_BREAK = 2
__QUARTZUI_TS__.TRY_CONTINUE = 3

local function __quartzui_ts_path(module, ...)
  if type(module) ~= "table" then
    error("[QuartzUI] TS.import: module is not a table", 3)
  end
  if module.__quartzuiExternal ~= nil then
    local p = module.__quartzuiExternal
    for i = 1, select("#", ...) do
      p = p .. "/" .. tostring(select(i, ...))
    end
    return p, true
  end
  local base = module.__quartzuiDir
  if base == nil then base = module.__quartzuiPath or "" end
  local segs = {}
  for i = 1, select("#", ...) do
    table.insert(segs, tostring(select(i, ...)))
  end
  local joined = table.concat(segs, "/")
  if base == nil or base == "" then
    return joined, false
  elseif joined == "" then
    return base, false
  end
  return base .. "/" .. joined, false
end

function __QUARTZUI_TS__.import(context, module, ...)
  local p, _isExternal = __quartzui_ts_path(module, ...)
  return __quartzui_require(p)
end

local __quartzui_external_mt = {}
__quartzui_external_mt.__index = function(self, key)
  if type(key) ~= "string" then return nil end
  if string.sub(key, 1, 2) == "__" then return nil end
  if key == "Name" or key == "ClassName" then return nil end
  local childId = rawget(self, "__quartzuiExternal") .. "/" .. key
  return setmetatable({
    __quartzuiExternal = childId,
    Name = key,
    ClassName = "Folder",
  }, __quartzui_external_mt)
end

local function __quartzui_make_external(id, name)
  return setmetatable({
    __quartzuiExternal = id,
    Name = name or id,
    ClassName = "Folder",
  }, __quartzui_external_mt)
end

function __QUARTZUI_TS__.getModule(context, scope, moduleName)
  if moduleName == nil then
    moduleName = scope
    scope = "@rbxts"
  end
  return __quartzui_make_external(scope .. "/" .. moduleName, moduleName)
end

function __QUARTZUI_TS__.instanceof(obj, class)
  if type(class) == "table" and type(class.instanceof) == "function" then
    return class.instanceof(obj)
  end
  if type(obj) == "table" then
    obj = getmetatable(obj)
    while obj ~= nil do
      if obj == class then return true end
      local mt = getmetatable(obj)
      if mt then obj = mt.__index else obj = nil end
    end
  end
  return false
end

local function __quartzui_make_promise(status, value)
  local p
  p = {
    __qzPromise = true,
    status = status,
    value = value,
    andThen = function(self, s, f)
      if self.status == "resolved" then
        if s then
          local ok, res = pcall(s, self.value)
          if ok then return __quartzui_make_promise("resolved", res) end
          return __quartzui_make_promise("rejected", res)
        end
        return self
      end
      if f then
        local ok, res = pcall(f, self.value)
        if ok then return __quartzui_make_promise("resolved", res) end
        return __quartzui_make_promise("rejected", res)
      end
      return self
    end,
    catch = function(self, f)
      if self.status == "rejected" and f then
        local ok, res = pcall(f, self.value)
        if ok then return __quartzui_make_promise("resolved", res) end
        return __quartzui_make_promise("rejected", res)
      end
      return self
    end,
    await = function(self)
      return self.status == "resolved", self.value
    end,
    awaitStatus = function(self)
      return self.status == "resolved" and "Resolved" or "Rejected", self.value
    end,
  }
  return p
end

function __QUARTZUI_TS__.async(callback)
  return function(...)
    local n = select("#", ...)
    local args = { ... }
    local ok, result = pcall(function()
      return callback(unpack(args, 1, n))
    end)
    if ok then return __quartzui_make_promise("resolved", result) end
    return __quartzui_make_promise("rejected", result)
  end
end

function __QUARTZUI_TS__.await(promise)
  if type(promise) ~= "table" or not promise.__qzPromise then
    return promise
  end
  if promise.status == "resolved" then return promise.value end
  error(promise.value, 2)
end

local function __quartzui_bit_sign(num)
  if bit32.btest(num, 2147483648) then
    return num - 4294967296
  end
  return num
end

function __QUARTZUI_TS__.bit_lrsh(a, b)
  return __quartzui_bit_sign(bit32.arshift(a, b))
end

function __QUARTZUI_TS__.try(tryFn, catchFn, finallyFn)
  local trySuccess, exitTypeOrTryError, returns = pcall(tryFn)
  local exitType, tryError
  if trySuccess then
    exitType = exitTypeOrTryError
  else
    tryError = exitTypeOrTryError
  end
  local catchSuccess = true
  local catchError
  if not trySuccess and catchFn then
    local newExitTypeOrCatchError, newReturns
    catchSuccess, newExitTypeOrCatchError, newReturns = pcall(catchFn, tryError)
    local newExitType
    if catchSuccess then
      newExitType = newExitTypeOrCatchError
    else
      catchError = newExitTypeOrCatchError
    end
    if newExitType then
      exitType, returns = newExitType, newReturns
    end
  end
  if finallyFn then
    local newExitType, newReturns = finallyFn()
    if newExitType then
      exitType, returns = newExitType, newReturns
    end
  end
  if
    exitType ~= __QUARTZUI_TS__.TRY_RETURN
    and exitType ~= __QUARTZUI_TS__.TRY_BREAK
    and exitType ~= __QUARTZUI_TS__.TRY_CONTINUE
  then
    if not catchSuccess then error(catchError, 2) end
    if not trySuccess and not catchFn then error(tryError, 2) end
  end
  return exitType, returns
end

function __QUARTZUI_TS__.generator(callback)
  local co = coroutine.create(callback)
  return {
    next = function(...)
      if coroutine.status(co) == "dead" then
        return { done = true }
      end
      local success, value = coroutine.resume(co, ...)
      if not success then error(value, 2) end
      return {
        value = value,
        done = coroutine.status(co) == "dead",
      }
    end,
  }
end

__QUARTZUI_TS__.Promise = {
  new = function(executor)
    local resolvedStatus, resolvedValue
    local function resolve(v) resolvedStatus, resolvedValue = "resolved", v end
    local function reject(v) resolvedStatus, resolvedValue = "rejected", v end
    local ok, err = pcall(executor, resolve, reject)
    if not ok then
      return __quartzui_make_promise("rejected", err)
    end
    return __quartzui_make_promise(resolvedStatus or "resolved", resolvedValue)
  end,
  resolve = function(v) return __quartzui_make_promise("resolved", v) end,
  reject = function(v) return __quartzui_make_promise("rejected", v) end,
  is = function(v) return type(v) == "table" and v.__qzPromise == true end,
  Status = { Resolved = "Resolved", Rejected = "Rejected", Started = "Started", Cancelled = "Cancelled" },
}

local function __quartzui_entry()
  local primary = __QUARTZUI_REGISTRY__["init"]
  if primary ~= nil then
    return __quartzui_require("init")
  end
  local fallback = __QUARTZUI_REGISTRY__["index"]
  if fallback ~= nil then
    return __quartzui_require("index")
  end
  local bootFallback = __QUARTZUI_REGISTRY__["init"]
  if bootFallback ~= nil then
    return __quartzui_require("init")
  end
  error("[QuartzUI] no entry module found (looked for init, index, init)", 2)
end


local __quartzui_result__ = __quartzui_entry()
return __quartzui_result__
